package com.gatekeeper.apikey.service;

import org.springframework.stereotype.Component;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Objects;

/**
 * Computes and verifies SHA-256 digests of high-entropy API key secrets.
 * <p>
 * <b>Cryptographic Rationale:</b>
 * Gatekeeper API key secrets contain 256 bits of cryptographic entropy generated by
 * {@link java.security.SecureRandom}. Because an attacker cannot mount dictionary or rainbow table
 * attacks against 256 bits of true randomness (which would require \(2^{256}\) computations),
 * memory-hard or intentionally slow key-derivation functions (like BCrypt, Argon2, or PBKDF2)
 * are neither necessary nor appropriate for high-throughput API gateway routing.
 * <p>
 * SHA-256 evaluates in sub-microsecond time, allowing Gatekeeper to verify incoming requests
 * at wire speed while guaranteeing that the raw secret is never stored in persistent databases.
 * <p>
 * <i>Note:</i> Administrator passwords are low-entropy human credentials and must <b>never</b>
 * use SHA-256; administrator authentication uses salted, slow BCrypt hashing.
 */
@Component
public class ApiKeyHasher {

    private static final String ALGORITHM = "SHA-256";
    private final HexFormat hexFormat = HexFormat.of();

    /**
     * Computes the SHA-256 hex digest of the raw API key secret material.
     *
     * @param secret raw secret material
     * @return 64-character lowercase hexadecimal digest
     */
    public String hashSecret(String secret) {
        Objects.requireNonNull(secret, "secret must not be null");
        byte[] digestBytes = computeSha256(secret.getBytes(StandardCharsets.UTF_8));
        return this.hexFormat.formatHex(digestBytes);
    }

    /**
     * Verifies that a presented secret matches the stored hex digest using constant-time comparison.
     *
     * @param secret       raw secret presented by the client
     * @param storedDigest expected 64-character hex digest stored in the database
     * @return true if secret matches digest, false otherwise
     */
    public boolean verify(String secret, String storedDigest) {
        if (secret == null || storedDigest == null || storedDigest.length() != 64) {
            return false;
        }

        byte[] actualDigest = computeSha256(secret.getBytes(StandardCharsets.UTF_8));
        byte[] expectedDigest;
        try {
            expectedDigest = this.hexFormat.parseHex(storedDigest);
        } catch (IllegalArgumentException e) {
            return false;
        }

        // Constant-time array comparison to prevent timing side-channel attacks
        return MessageDigest.isEqual(actualDigest, expectedDigest);
    }

    private byte[] computeSha256(byte[] input) {
        try {
            MessageDigest digest = MessageDigest.getInstance(ALGORITHM);
            return digest.digest(input);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("JVM environment lacks SHA-256 message digest support", e);
        }
    }
}
